    /**
     * @method
     * @name polymarket#fetchTime
     * @description fetches the current integer timestamp in milliseconds from the exchange server
     * @see https://docs.polymarket.com/perps/market-data
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {int} the current integer timestamp in milliseconds from the exchange server
     */
    public async override Task<Int64> FetchTime(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> response = await this.publicGetInfoTime(parameters);
        //
        //     { "time": 1788524530209 }
        //
        return this.safeInteger(response, "time") ?? 0;
    }

    /**
     * @method
     * @name polymarket#fetchStatus
     * @description the latest known information on the availability of the exchange api
     * @see https://docs.polymarket.com/perps/market-data
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [status structure]{@link https://docs.ccxt.com/#/?id=exchange-status-structure}
     */
    public async override Task<ccxt.Status> FetchStatus(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> response = await this.publicGetInfoExchange(parameters);
        //
        //     {
        //         "name": "Polymarket",
        //         "version": "1",
        //         "chain_id": 137,
        //         "contract": "0xDCa4af75705dbB50f62437045afF9921947917d2",
        //         "cancel_only": false,
        //         "engine_version": "0.0.69"
        //     }
        //
        bool? cancelOnly = this.safeBool(response, "cancel_only", false);
        return ccxt.BaseExchange.ToStatus(new Dictionary<string, object>() {             { "status", cancelOnly == true ? "maintenance" : "ok" },             { "updated", null },             { "eta", null },             { "url", null },             { "info", response },         });
    }

    /**
     * @method
     * @name polymarket#fetchCurrencies
     * @description fetches all available currencies on an exchange - every instrument base, the usd quote and the collateral asset
     * @see https://docs.polymarket.com/perps/market-data
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an associative dictionary of currencies
     */
    public async override Task<IDictionary<string, object>> fetchCurrencies(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        List<Task<List<object>>> promises = new List<Task<List<object>>> {this.publicGetInfoInstruments(parameters), this.publicGetInfoAssets(parameters)};
        List<object> responses = new List<object>(await Task.WhenAll(promises));
        List<object> instruments = this.safeList(responses, 0, new List<object>() {});
        List<object> assets = this.safeList(responses, 1, new List<object>() {});
        Dictionary<string, object> result = new Dictionary<string, object>() {};
        for (int i = 0; i < instruments.Count; i++)
        {
            object instrument = instruments[i];
            string? baseId = this.safeString(instrument, "base_asset");
            if ((baseId == null))
            {
                continue;
            }
            string? code = this.safeCurrencyCode(baseId);
            if (!(((code != null) && result.ContainsKey(code))))
            {
                // the venue tags each underlying with a category - only the
                // crypto ones are unified as crypto, equities, commodities and
                // indices map onto the other currency type
                string? category = this.safeString(instrument, "category");
                string currencyType = (category == "crypto") ? "crypto" : "other";
                result[(string)code] = this.safeCurrencyStructure(new Dictionary<string, object>() {
                    { "id", baseId },
                    { "code", code },
                    { "name", baseId },
                    { "info", instrument },
                    { "active", true },
                    { "deposit", false },
                    { "withdraw", false },
                    { "fee", null },
                    { "precision", this.parseNumber(this.parsePrecision(this.safeString(instrument, "quantity_decimals"))) },
                    { "type", currencyType },
                    { "networks", new Dictionary<string, object>() {} },
                });
            }
        }
        // every instrument quotes using usd
        result["USD"] = this.safeCurrencyStructure(new Dictionary<string, object>() {
            { "id", "USD" },
            { "code", "USD" },
            { "name", "USD" },
            { "info", new Dictionary<string, object>() {} },
            { "active", true },
            { "deposit", false },
            { "withdraw", false },
            { "fee", null },
            { "precision", this.parseNumber("0.01") },
            { "type", "fiat" },
            { "networks", new Dictionary<string, object>() {} },
        });
        for (int i = 0; i < assets.Count; i++)
        {
            object asset = assets[i];
            string? currencyId = this.safeString(asset, "asset");
            if ((currencyId == null))
            {
                continue;
            }
            string? code = this.safeCurrencyCode(currencyId);
            result[(string)code] = this.safeCurrencyStructure(new Dictionary<string, object>() {
                { "id", currencyId },
                { "code", code },
                { "name", currencyId },
                { "info", asset },
                { "active", true },
                { "deposit", true },
                { "withdraw", true },
                { "fee", this.safeNumber(asset, "withdrawal_fee") },
                { "precision", this.parseNumber(this.parsePrecision(this.safeString(asset, "decimals"))) },
                { "type", "crypto" },
                { "networks", new Dictionary<string, object>() {} },
            });
        }
        return ((IDictionary<string, object>)((object)(result)));
    }

    /**
     * @method
     * @name polymarket#fetchMarkets
     * @description retrieves data on all markets for polymarket perps
     * @see https://docs.polymarket.com/perps/market-data
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public async override Task<List<ccxt.MarketInterface>> FetchMarkets(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        List<object> response = await this.publicGetInfoInstruments(parameters);
        //
        //     [
        //         {
        //             "instrument_id": 1,
        //             "instrument_type": "perpetual",
        //             "category": "index",
        //             "isolated_only": false,
        //             "symbol": "SP500-USD",
        //             "base_asset": "SP500",
        //             "quote_asset": "pUSD",
        //             "funding_interval": "1h",
        //             "quantity_decimals": 5,
        //             "price_decimals": 1,
        //             "price_bounds": "0.05",
        //             "liquidation_fee": "0.005",
        //             "max_order_count": 200,
        //             "min_notional": "10",
        //             "max_market_notional": "1000000",
        //             "max_limit_notional": "5000000",
        //             "max_leverage": 20,
        //             "risk_tiers": [ { "lower_bound": "0", "max_leverage": 20 } ],
        //             "ui_live_time": 1785542400000
        //         }
        //     ]
        //
        return ccxt.BaseExchange.ToMarketInterfaceList(this.parseMarkets(response));
    }

    public override Dictionary<string, object> parseMarket(object market)
    {
        string? numericId = this.safeString(market, "instrument_id");
        string? venueSymbol = this.safeString(market, "symbol");
        string? baseId = this.safeString(market, "base_asset");
        // prices are denominated using USD while pUSD is the 1:1 collateral and settlement token
        string? settleId = this.safeString(market, "quote_asset");
        List<object> parts = venueSymbol.Split(new [] {"-"}, StringSplitOptions.None).ToList<object>();
        string? quoteId = this.safeString(parts, 1, "USD");
        object bs = this.safeCurrencyCode(baseId);
        string? quote = this.safeCurrencyCode(quoteId);
        string? settle = this.safeCurrencyCode(settleId);
        bool crossAllowed = !(this.safeBool(market, "isolated_only", false) == true);
        return this.safeMarketStructure(new Dictionary<string, object>() {
            { "id", numericId },
            { "symbol", add(add(add(add(bs, "/"), quote), ":"), settle) },
            { "base", bs },
            { "quote", quote },
            { "settle", settle },
            { "baseId", baseId },
            { "quoteId", quoteId },
            { "settleId", settleId },
            { "type", "swap" },
            { "spot", false },
            { "margin", false },
            { "swap", true },
            { "future", false },
            { "option", false },
            { "active", true },
            { "contract", true },
            { "linear", true },
            { "inverse", false },
            { "taker", this.parseNumber("0.0004") },
            { "maker", this.parseNumber("0.000125") },
            { "contractSize", this.parseNumber("1") },
            { "expiry", null },
            { "expiryDatetime", null },
            { "strike", null },
            { "optionType", null },
            { "marginModes", new Dictionary<string, object>() {
                { "cross", crossAllowed },
                { "isolated", true },
            } },
            { "precision", new Dictionary<string, object>() {
                { "amount", this.parseNumber(this.parsePrecision(this.safeString(market, "quantity_decimals"))) },
                { "price", this.parseNumber(this.parsePrecision(this.safeString(market, "price_decimals"))) },
            } },
            { "limits", new Dictionary<string, object>() {
                { "leverage", new Dictionary<string, object>() {
                    { "min", this.parseNumber("1") },
                    { "max", this.safeNumber(market, "max_leverage") },
                } },
                { "amount", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "price", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "cost", new Dictionary<string, object>() {
                    { "min", this.safeNumber(market, "min_notional") },
                    { "max", this.safeNumber(market, "max_limit_notional") },
                } },
            } },
            { "created", null },
            { "info", market },
        });
    }

    /**
     * @method
     * @name polymarket#fetchTicker
     * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market, merging the ticker, statistics and best bid and ask endpoints
     * @see https://docs.polymarket.com/perps/market-data
     * @param {string} symbol unified symbol of the market to fetch the ticker for
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/#/?id=ticker-structure}
     */
    public async override Task<ccxt.Ticker> FetchTicker(string symbol, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        Dictionary<string, object> market = this.market(symbol);
        string? symbolResolved = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
        // the tickers and statistics endpoints ignore the documented
        // instrument_id filter and always answer with every instrument, so
        // the single-market call reuses the bulk fetch and selects one row
        Dictionary<string, object> tickers = ccxt.BaseExchange.FromTickers(await this.FetchTickers(new List<object>() {symbolResolved}, parameters));
        IDictionary<string, object> ticker = this.safeDict(tickers, symbolResolved);
        if ((ticker == null))
        {
            throw new BadSymbol (((this.id + " fetchTicker() could not find a ticker for ") + symbolResolved)) ;
        }
        return ccxt.BaseExchange.ToTicker(ticker);
    }

    /**
     * @method
     * @name polymarket#fetchTickers
     * @description fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market, merging the ticker, statistics and best bid and ask endpoints
     * @see https://docs.polymarket.com/perps/market-data
     * @param {string[]} [symbols] unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/#/?id=ticker-structure}
     */
    public async override Task<ccxt.Tickers> FetchTickers(IList<object> symbols = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        IList<object> symbolsNormalized = this.marketSymbols(symbols);
        List<Task<List<object>>> promises = new List<Task<List<object>>> {this.publicGetInfoTickers(parameters), this.publicGetInfoStatistics(parameters), this.publicGetInfoBbo(parameters)};
        List<object> responses = new List<object>(await Task.WhenAll(promises));
        //
        // tickers
        //
        //     [
        //         {
        //             "instrument_id": 1,
        //             "symbol": "SP500-USD",
        //             "index_price": "7713.1",
        //             "mark_price": "7715",
        //             "last_price": "7714",
        //             "mid_price": "7715",
        //             "open_interest": "1101.82729",
        //             "funding_rate": "0.00000625",
        //             "next_funding": 1788548400000,
        //             "timestamp": 1788546972857
        //         }
        //     ]
        //
        // statistics
        //
        //     [
        //         {
        //             "instrument_id": 1,
        //             "symbol": "SP500-USD",
        //             "volume": "2087643.9565559996",
        //             "open_price": "7754.5",
        //             "klines": [ [ 1788458400000, "7754.5", "7754.5", "7751.4", "7751.4", "0.39184", 3 ] ]
        //         }
        //     ]
        //
        // bbo
        //
        //     [
        //         {
        //             "instrument_id": 1,
        //             "bid_price": "7715",
        //             "bid_quantity": "22.63803",
        //             "ask_price": "7715.1",
        //             "ask_quantity": "0.95534",
        //             "timestamp": 1788546975038
        //         }
        //     ]
        //
        Dictionary<string, object> merged = new Dictionary<string, object>() {};
        List<object> statistics = this.safeList(responses, 1, new List<object>() {});
        for (int i = 0; i < statistics.Count; i++)
        {
            object entry = statistics[i];
            string? instrumentId = this.safeString(entry, "instrument_id");
            // the 24 hourly kline rows are dropped from the merged payload to keep tickers light, candles are served by fetchOHLCV
            merged[(string)instrumentId] = this.omit(entry, "klines");
        }
        List<object> bbos = this.safeList(responses, 2, new List<object>() {});
        for (int i = 0; i < bbos.Count; i++)
        {
            object entry = bbos[i];
            string? instrumentId = this.safeString(entry, "instrument_id");
            IDictionary<string, object> previous = this.safeDict(merged, instrumentId, new Dictionary<string, object>() {});
            // the tickers endpoint timestamp wins the merge below because most unified fields come from it - bbo rows carry a slightly newer sampling time
            merged[(string)instrumentId] = this.extend(previous, entry);
        }
        List<object> tickers = this.safeList(responses, 0, new List<object>() {});
        List<object> result = new List<object>() {};
        for (int i = 0; i < tickers.Count; i++)
        {
            object entry = tickers[i];
            string? instrumentId = this.safeString(entry, "instrument_id");
            IDictionary<string, object> previous = this.safeDict(merged, instrumentId, new Dictionary<string, object>() {});
            result.Add(this.extend(previous, entry));
        }
        return ccxt.BaseExchange.ToTickers(this.parseTickers(result, symbolsNormalized));
    }

    public override ccxt.Ticker parseTicker(object ticker, object market = null)
    {
        //
        // merged row assembled by fetchTickers from the tickers, statistics and bbo endpoints
        //
        //     {
        //         "instrument_id": 1,
        //         "symbol": "SP500-USD",
        //         "volume": "2087643.9565559996",
        //         "open_price": "7754.5",
        //         "bid_price": "7715",
        //         "bid_quantity": "22.63803",
        //         "ask_price": "7715.1",
        //         "ask_quantity": "0.95534",
        //         "index_price": "7713.1",
        //         "mark_price": "7715",
        //         "last_price": "7714",
        //         "mid_price": "7715",
        //         "open_interest": "1101.82729",
        //         "funding_rate": "0.00000625",
        //         "next_funding": 1788548400000,
        //         "timestamp": 1788546972857
        //     }
        //
        string? marketId = this.safeString(ticker, "instrument_id");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        Int64? timestamp = this.safeInteger(ticker, "timestamp");
        return this.safeTicker(new Dictionary<string, object>() {
            { "symbol", (marketResolved != null && marketResolved.ContainsKey("symbol") ? marketResolved["symbol"] : null) },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "high", null },
            { "low", null },
            { "bid", this.safeString(ticker, "bid_price") },
            { "bidVolume", this.safeString(ticker, "bid_quantity") },
            { "ask", this.safeString(ticker, "ask_price") },
            { "askVolume", this.safeString(ticker, "ask_quantity") },
            { "vwap", null },
            { "open", this.safeString(ticker, "open_price") },
            { "close", this.safeString(ticker, "last_price") },
            { "last", this.safeString(ticker, "last_price") },
            { "previousClose", null },
            { "change", null },
            { "percentage", null },
            { "average", null },
            { "baseVolume", null },
            { "quoteVolume", this.safeString(ticker, "volume") },
            { "markPrice", this.safeString(ticker, "mark_price") },
            { "indexPrice", this.safeString(ticker, "index_price") },
            { "info", ticker },
        }, marketResolved);
    }

