    public override ccxt.Trade parseTrade(object trade, object market = null)
    {
        //
        //     {
        //         "trade_id": 3738280849593744,
        //         "instrument_id": 1,
        //         "side": "long",
        //         "price": "7714",
        //         "quantity": "0.00136",
        //         "timestamp": 1788546565789,
        //         "hash": "0x"
        //     }
        //
        string? marketId = this.safeString2(trade, "instrument_id", "iid");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        Int64? timestamp = this.safeInteger2(trade, "timestamp", "ts");
        string? side = this.safeStringLower(trade, "side");
        if (side == "long")
        {
            side = "buy";
        } else if (side == "short")
        {
            side = "sell";
        }
        bool? isTaker = this.safeBool(trade, "taker");
        string? takerOrMaker = null;
        if ((isTaker != null))
        {
            takerOrMaker = isTaker == true ? "taker" : "maker";
        }
        string? feeCost = this.safeString(trade, "fee");
        Dictionary<string, object> fee = null;
        if ((feeCost != null))
        {
            string? feeCurrencyId = this.safeString2(trade, "fee_asset", "fea");
            fee = new Dictionary<string, object>() {
                { "cost", feeCost },
                { "currency", this.safeCurrencyCode(feeCurrencyId) },
            };
        }
        return this.safeTrade(new Dictionary<string, object>() {
            { "id", this.safeString2(trade, "trade_id", "tid") },
            { "info", trade },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", (marketResolved != null && marketResolved.ContainsKey("symbol") ? marketResolved["symbol"] : null) },
            { "order", this.safeString2(trade, "order_id", "oid") },
            { "type", null },
            { "side", side },
            { "takerOrMaker", takerOrMaker },
            { "price", this.safeString2(trade, "price", "p") },
            { "amount", this.safeString2(trade, "quantity", "qty") },
            { "cost", null },
            { "fee", fee },
        }, marketResolved);
    }

    /**
     * @method
     * @name polymarket#fetchOHLCV
     * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
     * @see https://docs.polymarket.com/perps/market-data
     * @param {string} symbol unified symbol of the market to fetch OHLCV data for
     * @param {string} timeframe the length of time each candle represents
     * @param {int} [since] timestamp in ms of the earliest candle to fetch
     * @param {int} [limit] the maximum amount of candles to fetch, the venue serves at most 1000 per request
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms of the latest candle to fetch
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling the endpoint multiple times
     * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
     */
    public async override Task<List<ccxt.OHLCV>> FetchOHLCV(string symbol, string timeframe = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        string timeframeVar = timeframe;
        timeframeVar ??= "1m";
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        bool? paginate = false;
        object paramsOmitted = parameters;
        IList<object> paginateparamsOmittedVariable = (IList<object>)this.handleOptionAndParams(paramsOmitted, "fetchOHLCV", "paginate");
        paginate = isTrue(paginateparamsOmittedVariable[0]);
        paramsOmitted = paginateparamsOmittedVariable[1];
        if ((paginate == true))
        {
            return ccxt.BaseExchange.ToOHLCVList(await this.fetchPaginatedCallDeterministic("fetchOHLCV", symbol, since, limit,timeframeVar, paramsOmitted, 1000));
        }
        Dictionary<string, object> market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "instrument_id", (market.ContainsKey("id") ? market["id"] : null) },
            { "interval", this.safeString(this.timeframes, timeframeVar, timeframeVar) },
        };
        Int64? until = this.safeInteger(paramsOmitted, "until");
        if ((until != null))
        {
            paramsOmitted = this.omit(paramsOmitted, "until");
            request["end_timestamp"] = until;
        }
        Int64 duration = (this.parseTimeframe(timeframeVar) * 1000L);
        if ((since != null))
        {
            request["start_timestamp"] = since;
        } else
        {
            // the venue requires an explicit range start - the window covers
            // exactly the requested number of candle bins including the
            // current one, so the newest candle never falls off the range
            Int64? end = ((until != null)) ? until : this.milliseconds();
            Int64? requestedLimit = ((limit != null)) ? limit : 100;
            request["start_timestamp"] = (end - (((requestedLimit - 1)) * duration));
        }
        Dictionary<string, object> response = await this.publicGetInfoKlines(this.extend(request, paramsOmitted));
        //
        //     {
        //         "data": [
        //             [ 1788458400000, "7754.5", "7754.5", "7751.4", "7751.4", "0.39184", 3 ]
        //         ],
        //         "more": false
        //     }
        //
        List<object> data = this.safeList(response, "data", new List<object>() {});
        return ccxt.BaseExchange.ToOHLCVList(this.parseOHLCVs(data, market,timeframeVar, since, limit));
    }

    public override IList<object> parseOHLCV(object ohlcv, object market = null)
    {
        //
        // rows carry the timestamp, open, high, low, close, base volume and the trade count
        //
        //     [ 1788458400000, "7754.5", "7754.5", "7751.4", "7751.4", "0.39184", 3 ]
        //
        return new List<object> {this.safeInteger(ohlcv, 0), this.safeNumber(ohlcv, 1), this.safeNumber(ohlcv, 2), this.safeNumber(ohlcv, 3), this.safeNumber(ohlcv, 4), this.safeNumber(ohlcv, 5)};
    }

