    public override Dictionary<string, object> parseFundingRate(object contract, IDictionary<string, object> market = null)
    {
        //
        //     {
        //         "instrument_id": 1,
        //         "symbol": "SP500-USD",
        //         "index_price": "7713.1",
        //         "mark_price": "7715",
        //         "last_price": "7714",
        //         "mid_price": "7715",
        //         "open_interest": "1101.82729",
        //         "funding_rate": "0.00000625",
        //         "next_funding": 1788548400000,
        //         "timestamp": 1788546972857
        //     }
        //
        string? marketId = this.safeString(contract, "instrument_id");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        Int64? timestamp = this.safeInteger(contract, "timestamp");
        Int64? nextFundingTimestamp = this.safeInteger(contract, "next_funding");
        string? interval = this.safeString((marketResolved != null && marketResolved.ContainsKey("info") ? marketResolved["info"] : null), "funding_interval");
        return new Dictionary<string, object>() {
            { "info", contract },
            { "symbol", (marketResolved != null && marketResolved.ContainsKey("symbol") ? marketResolved["symbol"] : null) },
            { "markPrice", this.safeNumber(contract, "mark_price") },
            { "indexPrice", this.safeNumber(contract, "index_price") },
            { "interestRate", null },
            { "estimatedSettlePrice", null },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "fundingRate", this.safeNumber(contract, "funding_rate") },
            { "fundingTimestamp", null },
            { "fundingDatetime", null },
            { "nextFundingRate", null },
            { "nextFundingTimestamp", nextFundingTimestamp },
            { "nextFundingDatetime", this.iso8601(nextFundingTimestamp) },
            { "previousFundingRate", null },
            { "previousFundingTimestamp", null },
            { "previousFundingDatetime", null },
            { "interval", interval },
        };
    }

    /**
     * @method
     * @name polymarket#fetchFundingRateHistory
     * @description fetches historical funding rate prices
     * @see https://docs.polymarket.com/perps/market-data
     * @param {string} symbol unified symbol of the market to fetch the funding rate history for
     * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
     * @param {int} [limit] the maximum amount of funding rate structures to fetch, the venue serves at most 100 per request
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms of the latest funding rate to fetch
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling the endpoint multiple times
     * @returns {object[]} a list of [funding rate structures]{@link https://docs.ccxt.com/#/?id=funding-rate-history-structure}
     */
    public async override Task<List<ccxt.FundingRateHistory>> FetchFundingRateHistory(string symbol = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((symbol == null))
        {
            throw new ArgumentsRequired ((this.id + " fetchFundingRateHistory() requires a symbol argument")) ;
        }
        await this.loadMarkets();
        bool? paginate = false;
        object paramsOmitted = parameters;
        IList<object> paginateparamsOmittedVariable = (IList<object>)this.handleOptionAndParams(paramsOmitted, "fetchFundingRateHistory", "paginate");
        paginate = isTrue(paginateparamsOmittedVariable[0]);
        paramsOmitted = paginateparamsOmittedVariable[1];
        if ((paginate == true))
        {
            return ccxt.BaseExchange.ToFundingRateHistoryList(await this.fetchPaginatedCallDeterministic("fetchFundingRateHistory", symbol, since, limit, "1h", paramsOmitted, 100));
        }
        Dictionary<string, object> market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "instrument_id", (market.ContainsKey("id") ? market["id"] : null) },
        };
        if ((since != null))
        {
            request["start_timestamp"] = since;
        }
        Int64? until = this.safeInteger(paramsOmitted, "until");
        if ((until != null))
        {
            paramsOmitted = this.omit(paramsOmitted, "until");
            request["end_timestamp"] = until;
        }
        Dictionary<string, object> response = await this.publicGetInfoFunding(this.extend(request, paramsOmitted));
        //
        //     {
        //         "data": [
        //             { "funding_rate": "0.00000625", "timestamp": 1788544800063 }
        //         ],
        //         "more": false
        //     }
        //
        List<object> data = this.safeList(response, "data", new List<object>() {});
        List<object> rates = new List<object>() {};
        for (int i = 0; i < data.Count; i++)
        {
            object entry = data[i];
            Int64? timestamp = this.safeInteger(entry, "timestamp");
            rates.Add(new Dictionary<string, object>() {
                { "info", entry },
                { "symbol", (market.ContainsKey("symbol") ? market["symbol"] : null) },
                { "fundingRate", this.safeNumber(entry, "funding_rate") },
                { "timestamp", timestamp },
                { "datetime", this.iso8601(timestamp) },
            });
        }
        List<object> sorted = this.sortBy(rates, "timestamp");
        return ccxt.BaseExchange.ToFundingRateHistoryList(this.filterBySymbolSinceLimit(sorted, (market.ContainsKey("symbol") ? market["symbol"] : null), since, limit));
    }

    /**
     * @method
     * @name polymarket#fetchOpenInterest
     * @description retrieves the open interest of a contract trading pair
     * @see https://docs.polymarket.com/perps/market-data
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [open interest structure]{@link https://docs.ccxt.com/#/?id=open-interest-structure}
     */
    public async override Task<ccxt.OpenInterest> FetchOpenInterest(string symbol, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        Dictionary<string, object> market = this.market(symbol);
        string? symbolResolved = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
        // the tickers endpoint ignores the documented instrument_id filter
        // and always answers with every instrument, so the single-market call
        // reuses the bulk fetch and selects the requested row
        Dictionary<string, object> openInterests = ccxt.BaseExchange.FromOpenInterests(await this.FetchOpenInterests(new List<object>() {symbolResolved}, parameters));
        IDictionary<string, object> openInterest = this.safeDict(openInterests, symbolResolved);
        if ((openInterest == null))
        {
            throw new BadSymbol (((this.id + " fetchOpenInterest() could not find the open interest for ") + symbolResolved)) ;
