    public override Dictionary<string, object> parseOpenInterest(object interest, IDictionary<string, object> market = null)
    {
        //
        //     {
        //         "instrument_id": 1,
        //         "symbol": "SP500-USD",
        //         "index_price": "7713.1",
        //         "mark_price": "7715",
        //         "last_price": "7714",
        //         "mid_price": "7715",
        //         "open_interest": "1101.82729",
        //         "funding_rate": "0.00000625",
        //         "next_funding": 1788548400000,
        //         "timestamp": 1788546972857
        //     }
        //
        string? marketId = this.safeString(interest, "instrument_id");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        Int64? timestamp = this.safeInteger(interest, "timestamp");
        return this.safeOpenInterest(new Dictionary<string, object>() {
            { "symbol", (marketResolved != null && marketResolved.ContainsKey("symbol") ? marketResolved["symbol"] : null) },
            { "openInterestAmount", this.safeString(interest, "open_interest") },
            { "openInterestValue", null },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "info", interest },
        }, marketResolved);
    }

    /**
     * @method
     * @name polymarket#fetchTradingFees
     * @description fetches the default trading fees for multiple markets
     * @see https://docs.polymarket.com/perps/learn-about-trading/fees
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a dictionary of [fee structures]{@link https://docs.ccxt.com/#/?id=fee-structure} indexed by market symbols
     */
    public async override Task<ccxt.TradingFees> FetchTradingFees(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        Dictionary<string, object> response = await this.publicGetInfoFees(parameters);
        //
        //     {
        //         "fee_schedule": [
        //             {
        //                 "instrument_type": "perpetual",
        //                 "category": "equity",
        //                 "taker_fee_rate": "0.0004",
        //                 "maker_fee_rate": "0.000125",
        //                 "tiers": [ { "min_volume_30d": "0", "taker_fee_rate": "0.0004", "maker_fee_rate": "0.000125" } ]
        //             }
        //         ]
        //     }
        //
        List<object> schedule = this.safeList(response, "fee_schedule", new List<object>() {});
        Dictionary<string, object> byCategory = new Dictionary<string, object>() {};
        for (int i = 0; i < schedule.Count; i++)
        {
            object entry = schedule[i];
            string? category = this.safeString(entry, "category");
            byCategory[(string)category] = entry;
        }
        IDictionary<string, object> fallback = this.safeDict(schedule, 0, new Dictionary<string, object>() {});
        Dictionary<string, object> result = new Dictionary<string, object>() {};
        for (int i = 0; i < this.symbols.Count; i++)
        {
            string? symbol = this.safeString(this.symbols, i, "");
            Dictionary<string, object> market = this.market(symbol);
            string? category = this.safeString((market.ContainsKey("info") ? market["info"] : null), "category");
            IDictionary<string, object> entry = this.safeDict(byCategory, category, fallback);
            result[(string)symbol] = new Dictionary<string, object>() {
                { "info", entry },
                { "symbol", symbol },
                { "maker", this.safeNumber(entry, "maker_fee_rate") },
                { "taker", this.safeNumber(entry, "taker_fee_rate") },
                { "percentage", true },
                { "tierBased", true },
            };
        }
        return ccxt.BaseExchange.ToTradingFees(result);
    }

    /**
     * @method
     * @ignore
     * @name polymarket#createOrderRequest
     * @description builds one order for the createOrders operation, returning the compact signable row next to the structured body entry
     * @param {object} market the market the order targets
     * @param {string} type 'market' or 'limit'
     * @param {string} side 'buy' or 'sell'
     * @param {float} amount how much you want to trade in units of the base currency
     * @param {float} [price] the price to fulfill the order at, a market order can carry one to act like a protective bound
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a dict with the signable row and the body entry
     */
    public virtual Dictionary<string, object> createOrderRequest(IDictionary<string, object> market, object type, object side, object amount, object price = null, IDictionary<string, object>? parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        string? triggerPrice = this.safeStringN(parameters, new List<object>() {"triggerPrice", "stopPrice", "stopLossPrice", "takeProfitPrice", "trailingPercent", "trailingAmount"});
        object attached = this.safeValueN(parameters, new List<object>() {"stopLoss", "takeProfit"});
        if (((triggerPrice != null)) || ((attached != null)))
        {
            throw new NotSupported ((this.id + " createOrder() does not support trigger or attached stop orders yet")) ;
        }
        string? symbol = this.safeSymbol(null, market);
        bool isMarketOrder = ((type is "market"));
        string? timeInForce = this.safeStringUpper(parameters, "timeInForce");
        bool isPostOnlyTimeInForce = (timeInForce == "PO");
        bool? postOnly = false;
        object paramsOmitted = parameters;
        IList<object> postOnlyparamsOmittedVariable = (IList<object>)this.handlePostOnly(isMarketOrder, isPostOnlyTimeInForce, paramsOmitted);
        postOnly = (bool?)postOnlyparamsOmittedVariable[0];
        paramsOmitted = postOnlyparamsOmittedVariable[1];
        if (isMarketOrder)
        {
            if ((timeInForce == "GTC") || (timeInForce == "PO"))
            {
                throw new NotSupported ((((this.id + " createOrder() does not support the ") + timeInForce) + " timeInForce on market orders")) ;
            }
            if ((timeInForce == null))
            {
                timeInForce = "IOC";
            }
        } else
        {
            if ((price == null))
            {
                throw new ArgumentsRequired ((this.id + " createOrder() requires a price argument for limit orders")) ;
            }
            if (((timeInForce == null)) || (timeInForce == "PO"))
            {
                timeInForce = "GTC";
            }
        }
        string tif = timeInForce.ToLower();
        bool? reduceOnly = this.safeBool(paramsOmitted, "reduceOnly", false);
        string? clientOrderId = this.safeString2(paramsOmitted, "clientOrderId", "c");
        paramsOmitted = this.omit(paramsOmitted, new List<object>() {"timeInForce", "reduceOnly", "clientOrderId"});
        Int64? instrumentId = this.parseToInt((market != null && market.ContainsKey("id") ? market["id"] : null));
        bool isBuy = ((side is "buy"));
        string? quantity = this.amountToPrecision(symbol, amount);
        string? priceString = null;
        if ((price != null))
        {
            priceString = this.priceToPrecision(symbol, price);
        }
        bool? reduceOnlyValue = reduceOnly == true ? true : null;
        // the signable row is positional - iid, buy, p, qty, tif, po, ro, c,
        // trigger - undefined entries are removed and later entries shift left,
        // the venue rebuilds the same compact array from the body to verify
        List<object> row = new List<object>() {instrumentId, isBuy, priceString, quantity, tif, postOnly, reduceOnlyValue, clientOrderId};
        object signable = this.compactSignable(row);
        Dictionary<string, object> entry = new Dictionary<string, object>() {
            { "iid", instrumentId },
            { "buy", isBuy },
            { "po", postOnly },
            { "qty", quantity },
            { "tif", tif },
        };
        if ((priceString != null))
        {
            entry["p"] = priceString;
        }
        if ((reduceOnlyValue != null))
        {
            entry["ro"] = reduceOnlyValue;
        }
        if ((clientOrderId != null))
        {
            entry["c"] = clientOrderId;
        }
        return new Dictionary<string, object>() {
            { "signable", signable },
            { "entry", entry },
            { "params", paramsOmitted },
        };
    }

    /**
     * @method
     * @name polymarket#createOrder
     * @description create a trade order
     * @see https://docs.polymarket.com/perps/trading
     * @param {string} symbol unified symbol of the market to create an order in
     * @param {string} type 'market' or 'limit', a market order executes like an immediate-or-cancel order without a price
     * @param {string} side 'buy' or 'sell'
     * @param {float} amount how much you want to trade in units of the base currency
     * @param {float} [price] the price to fulfill the order at, a market order accepts one to act like a protective bound
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.timeInForce] 'GTC', 'IOC', 'FOK' or 'PO'
     * @param {bool} [params.postOnly] true to place a maker only order
     * @param {bool} [params.reduceOnly] true to reduce an open position only
     * @param {string} [params.clientOrderId] a client order id, exactly 32 lowercase hex characters
     * @param {int} [params.exp] expiry timestamp of the signed command in ms, bounds how long the gateway may hold the request
     * @returns {object} an [order structure]{@link https://docs.ccxt.com/#/?id=order-structure}
     */
    public async override Task<ccxt.Order> CreateOrder(string symbol, string type, string side, double amount, double? price = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        Dictionary<string, object> order = new Dictionary<string, object>() {
            { "symbol", symbol },
            { "type", type },
            { "side", side },
            { "amount", amount },
            { "price", price },
            { "params", parameters },
        };
        List<object> orders = ccxt.BaseExchange.FromOrderList(await this.CreateOrders(new List<object>() {order}, parameters));
        IDictionary<string, object> first = this.safeDict(orders, 0, new Dictionary<string, object>() {});
        string? firstStatus = this.safeString(first, "status");
        if (firstStatus == "rejected")
        {
            IDictionary<string, object> firstInfo = this.safeDict(first, "info", new Dictionary<string, object>() {});
            string? errorId = this.safeString(firstInfo, "error");
            string feedback = ((this.id + " createOrder() rejected: ") + this.json(firstInfo));
            this.throwExactlyMatchedException((this.exceptions != null && ((IDictionary<string, object>)this.exceptions).ContainsKey("exact") ? ((IDictionary<string, object>)this.exceptions)["exact"] : null), errorId, feedback);
            this.throwBroadlyMatchedException((this.exceptions != null && ((IDictionary<string, object>)this.exceptions).ContainsKey("broad") ? ((IDictionary<string, object>)this.exceptions)["broad"] : null), errorId, feedback);
            throw new InvalidOrder (feedback) ;
        }
        IDictionary<string, object> created = this.safeDict(orders, 0);
        return ccxt.BaseExchange.ToOrder(created);
    }

    /**
     * @method
     * @name polymarket#createOrders
     * @description create a list of trade orders in one signed batch
     * @see https://docs.polymarket.com/perps/trading
     * @param {Array} orders list of orders to create, each object should contain the parameters required by createOrder, namely symbol, type, side, amount, price and params
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.exp] expiry timestamp of the signed command in ms, bounds how long the gateway may hold the request
     * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/#/?id=order-structure}
     */
    public async override Task<List<ccxt.Order>> CreateOrders(IList<object> orders, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        List<object> rows = new List<object>() {};
        List<object> entries = new List<object>() {};
        List<object> ordersMarkets = new List<object>() {};
        List<object> ordersEntries = new List<object>() {};
        for (int i = 0; i < (orders?.Count ?? 0); i++)
        {
            IDictionary<string, object> rawOrder = ((IDictionary<string, object>)(orders != null && i < orders.Count ? orders[i] : null));
            string? symbol = this.safeString(rawOrder, "symbol");
            Dictionary<string, object> market = this.market(symbol);
            string? type = this.safeStringLower(rawOrder, "type");
            string? side = this.safeStringLower(rawOrder, "side");
            string? amount = this.safeString(rawOrder, "amount");
            string? price = this.safeString(rawOrder, "price");
            IDictionary<string, object> orderParams = this.safeDict(rawOrder, "params", new Dictionary<string, object>() {});
            Dictionary<string, object> request = this.createOrderRequest(market, type, side, amount, price, orderParams);
            rows.Add((request != null && request.ContainsKey("signable") ? request["signable"] : null));
            entries.Add((request != null && request.ContainsKey("entry") ? request["entry"] : null));
            ordersMarkets.Add(market);
            ordersEntries.Add((request != null && request.ContainsKey("entry") ? request["entry"] : null));
        }
        List<object> signable = new List<object>() {"createOrders", rows};
        Dictionary<string, object> bodyOp = new Dictionary<string, object>() {
            { "type", "createOrders" },
            { "args", entries },
        };
        object signed = await this.signPerpsOp(signable, bodyOp, parameters);
        List<object> response = await this.tradePostTradeOrders(signed);
        //
        //     [
        //         { "status": "ok", "oid": 1234567890, "coid": "aabbccdd..." }
        //     ]
        //
        List<object> results = new List<object>() {};
        for (int i = 0; i < (response?.Count ?? 0); i++)
        {
            IDictionary<string, object> ack = this.safeDict(response, i, new Dictionary<string, object>() {});
            Dictionary<string, object> marketInner = ((Dictionary<string, object>)(ordersMarkets != null && i < ordersMarkets.Count ? ordersMarkets[i] : null));
            IDictionary<string, object> echo = this.safeDict(ordersEntries, i, new Dictionary<string, object>() {});
            string? status = this.safeString(ack, "status");
            Dictionary<string, object> merged = this.extend(echo, new Dictionary<string, object>() {
                { "oid", this.safeInteger(ack, "oid") },
                { "coid", this.safeString2(ack, "coid", "c") },
            });
            if (status == "err")
            {
                merged["status"] = "rejected";
            } else
            {
                merged["status"] = null;
            }
            Dictionary<string, object> parsed = ccxt.BaseExchange.FromOrder(this.parseOrder(merged, marketInner));
            parsed["info"] = ack;
            results.Add(parsed);
        }
        return ccxt.BaseExchange.ToOrderList(results);
    }

    /**
     * @method
     * @name polymarket#cancelOrder
     * @description cancels an open order
     * @see https://docs.polymarket.com/perps/trading
     * @param {string} id order id
     * @param {string} [symbol] not used by polymarket cancelOrder
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.clientOrderId] cancel by the client order id instead of the exchange order id
     * @returns {object} an [order structure]{@link https://docs.ccxt.com/#/?id=order-structure}
     */
    public async override Task<ccxt.Order> CancelOrder(string id, string symbol = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        List<object> orders = ccxt.BaseExchange.FromOrderList(await this.CancelOrders(new List<object>() {id}, symbol, parameters));
        IDictionary<string, object> canceled = this.safeDict(orders, 0);
        return ccxt.BaseExchange.ToOrder(canceled);
    }

    /**
     * @method
     * @name polymarket#cancelOrders
     * @description cancel multiple orders in one signed batch
     * @see https://docs.polymarket.com/perps/trading
     * @param {string[]} ids order ids
     * @param {string} [symbol] not used by polymarket cancelOrders
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string[]} [params.clientOrderIds] cancel by client order ids instead of the exchange order ids
     * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/#/?id=order-structure}
     */
    public async override Task<List<ccxt.Order>> CancelOrders(IList<object> ids, string symbol = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        List<object> clientOrderIds = this.safeList2(parameters, "clientOrderIds", "clientOrderId");
        if ((clientOrderIds == null))
        {
            string? clientOrderId = this.safeString(parameters, "clientOrderId");
            if ((clientOrderId != null))
            {
                clientOrderIds = new List<object>() {clientOrderId};
            }
        }
        IDictionary<string, object> paramsOmitted = ((IDictionary<string, object>)this.omit(parameters, new List<object>() {"clientOrderIds", "clientOrderId"}));
        List<object> signable = null;
        Dictionary<string, object> bodyOp = null;
        List<object> response = null;
        if ((clientOrderIds != null))
        {
            signable = new List<object>() {"cancelOrdersCOID", clientOrderIds};
            bodyOp = new Dictionary<string, object>() {
                { "type", "cancelOrdersCOID" },
                { "args", clientOrderIds },
            };
            object signed = await this.signPerpsOp(signable, bodyOp, paramsOmitted);
            response = await this.tradeDeleteTradeOrdersCoid(signed);
        } else
        {
            List<object> numericIds = new List<object>() {};
            for (int i = 0; i < (ids?.Count ?? 0); i++)
            {
                numericIds.Add(this.parseToInt(this.safeString(ids, i)));
            }
            signable = new List<object>() {"cancelOrders", numericIds};
            bodyOp = new Dictionary<string, object>() {
                { "type", "cancelOrders" },
                { "args", numericIds },
            };
            object signed = await this.signPerpsOp(signable, bodyOp, paramsOmitted);
            response = await this.tradeDeleteTradeOrders(signed);
        }
        //
        //     [
        //         { "status": "ok", "oid": 1234567890, "ts": 1788546565789 }
        //     ]
        //
        List<object> results = new List<object>() {};
        for (int i = 0; i < (response?.Count ?? 0); i++)
        {
            IDictionary<string, object> ack = this.safeDict(response, i, new Dictionary<string, object>() {});
            string? status = this.safeString(ack, "status");
            string unified = (status == "err") ? "rejected" : "canceled";
            Dictionary<string, object> merged = new Dictionary<string, object>() {
                { "oid", this.safeInteger(ack, "oid") },
                { "coid", this.safeString(ack, "coid") },
                { "uts", this.safeInteger(ack, "ts") },
                { "status", unified },
            };
            Dictionary<string, object> parsed = ccxt.BaseExchange.FromOrder(this.parseOrder(merged));
            parsed["info"] = ack;
            results.Add(parsed);
        }
        return ccxt.BaseExchange.ToOrderList(results);
    }

    /**
     * @method
     * @name polymarket#cancelAllOrders
     * @description cancel all open orders, optionally scoped to a single market
     * @see https://docs.polymarket.com/perps/trading
     * @param {string} [symbol] unified market symbol, cancels the orders of every market when omitted
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list with the raw acknowledgement of the venue
     */
    public async override Task<List<ccxt.Order>> CancelAllOrders(string symbol = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        Dictionary<string, object> args = new Dictionary<string, object>() {};
        List<object> signableArgs = new List<object>() {};
        if ((symbol != null))
        {
            Dictionary<string, object> market = this.market(symbol);
            Int64? instrumentId = this.parseToInt((market.ContainsKey("id") ? market["id"] : null));
            args["iid"] = instrumentId;
            signableArgs = new List<object>() {instrumentId};
        }
        List<object> signable = new List<object>() {"cancelAll", signableArgs};
        Dictionary<string, object> bodyOp = new Dictionary<string, object>() {
