            { "args", args },
        };
        object signed = await this.signPerpsOp(signable, bodyOp);
        Dictionary<string, object> response = await this.tradeDeleteTradeOrdersAll(signed);
        //
        //     { "status": "ok" }
        //
        return ccxt.BaseExchange.ToOrderList(new List<object> {ccxt.BaseExchange.FromOrder(this.safeOrder(new Dictionary<string, object>() {     { "info", response }, }))});
    }

    /**
     * @method
     * @name polymarket#cancelAllOrdersAfter
     * @description arms or clears a dead man's switch that cancels every open order once the deadline passes
     * @see https://docs.polymarket.com/perps/trading
     * @param {number} timeout time in milliseconds, 0 represents cancel the timer, the venue requires at least 5 seconds
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} the raw acknowledgement of the venue
     */
    public async override Task<Dictionary<string, object>> CancelAllOrdersAfter(Int64? timeout, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        object deadline = 0;
        if (((timeout != null)) && ((timeout > 0)))
        {
            deadline = this.sum(this.milliseconds(), timeout);
        }
        List<object> signable = new List<object>() {"autoCancel", new List<object>() {deadline}};
        Dictionary<string, object> bodyOp = new Dictionary<string, object>() {
            { "type", "autoCancel" },
            { "args", new Dictionary<string, object>() {
                { "time", deadline },
            } },
        };
        object signed = await this.signPerpsOp(signable, bodyOp);
        Dictionary<string, object> response = await this.tradePatchTradeAutoCancel(signed);
        //
        //     { "status": "ok", "deadline": 1788546570789 }
        //
        return response;
    }

    /**
     * @method
     * @name polymarket#editOrder
     * @description edit a resting standalone gtc limit order, only the price and the total quantity can change
     * @see https://docs.polymarket.com/perps/trading
     * @param {string} id order id
     * @param {string} symbol unified symbol of the market the order was made in
     * @param {string} type not used by polymarket editOrder
     * @param {string} side not used by polymarket editOrder
     * @param {float} amount the new total order quantity, it must exceed the already filled quantity
     * @param {float} price the new order price
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order structure]{@link https://docs.ccxt.com/#/?id=order-structure}
     */
    public async override Task<ccxt.Order> EditOrder(string id, string symbol, string type, string side, double? amount = null, double? price = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        Dictionary<string, object> market = this.market(symbol);
        if (((amount == null)) || ((price == null)))
        {
            throw new ArgumentsRequired ((this.id + " editOrder() requires both the amount and the price arguments")) ;
        }
        Int64? orderId = this.parseToInt(id);
        string? priceString = this.priceToPrecision((market.ContainsKey("symbol") ? market["symbol"] : null), price);
        string? quantity = this.amountToPrecision((market.ContainsKey("symbol") ? market["symbol"] : null), amount);
        List<object> signable = new List<object>() {"modifyOrders", new List<object>() {new List<object>() {orderId, priceString, quantity}}};
        Dictionary<string, object> bodyOp = new Dictionary<string, object>() {
            { "type", "modifyOrders" },
            { "args", new List<object>() {new Dictionary<string, object>() {
    { "oid", orderId },
    { "p", priceString },
    { "qty", quantity },
}} },
        };
        object signed = await this.signPerpsOp(signable, bodyOp, parameters);
        List<object> response = await this.tradePatchTradeOrders(signed);
        //
        //     [
        //         {
        //             "status": "ok",
        //             "order": { "oid": 1, "iid": 1, "buy": true, "p": "7700", "qty": "0.001", "tif": "gtc", "po": false, "ro": false, "rest": "0.001", "fill": "0", "cts": 1788546565789, "uts": 1788546565789, "status": "open" }
        //         }
        //     ]
        //
        IDictionary<string, object> first = this.safeDict(response, 0, new Dictionary<string, object>() {});
        string? status = this.safeString(first, "status");
        if (status == "err")
        {
            Dictionary<string, object> merged = new Dictionary<string, object>() {
                { "oid", this.safeInteger(first, "oid") },
                { "coid", this.safeString(first, "coid") },
                { "status", "rejected" },
            };
            Dictionary<string, object> rejected = ccxt.BaseExchange.FromOrder(this.parseOrder(merged, market));
            rejected["info"] = first;
            return ccxt.BaseExchange.ToOrder(rejected);
        }
        IDictionary<string, object> order = this.safeDict(first, "order", new Dictionary<string, object>() {});
        return this.parseOrder(order, market);
    }

    public virtual string? parseOrderStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "accepted", "open" },
            { "open", "open" },
            { "partial", "open" },
            { "untriggered", "open" },
            { "armed", "open" },
            { "triggered", "open" },
            { "filled", "closed" },
            { "cancelled", "canceled" },
            { "auto_cancelled", "canceled" },
            { "fok_unfilled", "canceled" },
            { "ioc_no_fill", "canceled" },
            { "ioc_expired", "canceled" },
            { "stp_cancelled", "canceled" },
            { "reduce_only_expired", "canceled" },
            { "parent_cancelled", "canceled" },
            { "position_closed", "canceled" },
            { "position_flipped", "canceled" },
            { "reduce_only_invalid_at_trigger", "canceled" },
            { "order_expired", "expired" },
            { "expired", "expired" },
            { "post_only_rejected", "rejected" },
            { "zero_quantity", "rejected" },
            { "duplicate_order", "rejected" },
            { "order_not_found", "rejected" },
            { "reduce_only_invalid", "rejected" },
        };
        return this.safeString(statuses, status, status);
    }

    public override ccxt.Order parseOrder(object order, IDictionary<string, object> market = null)
    {
        //
        // GET /v1/account/orders and /v1/account/open-orders use long names
        //
        //     {
        //         "order_id": 1234567890,
        //         "instrument_id": 1,
        //         "buy": true,
        //         "price": "7700.0",
        //         "quantity": "0.001",
        //         "tif": "gtc",
        //         "post_only": false,
        //         "ro": false,
        //         "resting_quantity": "0.001",
        //         "filled_quantity": "0",
        //         "status": "open",
        //         "created_timestamp": 1788546565789,
        //         "updated_timestamp": 1788546565789,
        //         "client_order_id": "aabbccddaabbccddaabbccddaabbccdd"
        //     }
        //
        // the modify acknowledgement and the ws orders channel use short names
        //
        //     {
        //         "oid": 1234567890,
        //         "iid": 1,
        //         "buy": true,
        //         "p": "7700.0",
        //         "qty": "0.001",
        //         "tif": "gtc",
        //         "po": false,
        //         "ro": false,
        //         "rest": "0.001",
        //         "fill": "0",
        //         "cts": 1788546565789,
        //         "uts": 1788546565789,
        //         "status": "open"
        //     }
        //
        string? marketId = this.safeString2(order, "instrument_id", "iid");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        Int64? timestamp = this.safeInteger2(order, "created_timestamp", "cts");
        Int64? lastUpdateTimestamp = this.safeInteger2(order, "updated_timestamp", "uts");
        bool? isBuy = this.safeBool(order, "buy");
        string? side = null;
        if ((isBuy != null))
        {
            side = isBuy == true ? "buy" : "sell";
        }
        string? price = ((string)this.omitZero(this.safeString2(order, "price", "p")));
        string? type = null;
        string? tif = this.safeString(order, "tif");
        if ((tif != null))
        {
            type = ((price == null)) ? "market" : "limit";
        }
        IDictionary<string, object> tpsl = this.safeDict(order, "tpsl");
        string? stopLossPrice = null;
        string? takeProfitPrice = null;
        if ((tpsl != null))
        {
            string? kind = this.safeString(tpsl, "kind");
            string? triggerValue = this.safeString(tpsl, "trp");
            if (kind == "sl")
            {
                stopLossPrice = triggerValue;
            } else if (kind == "tp")
            {
                takeProfitPrice = triggerValue;
            }
        }
        return this.safeOrder(new Dictionary<string, object>() {
            { "info", order },
            { "id", this.safeString2(order, "order_id", "oid") },
            { "clientOrderId", this.safeString2(order, "client_order_id", "coid") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", null },
            { "lastUpdateTimestamp", lastUpdateTimestamp },
            { "symbol", (marketResolved != null && marketResolved.ContainsKey("symbol") ? marketResolved["symbol"] : null) },
            { "type", type },
            { "timeInForce", this.safeStringUpper(order, "tif") },
            { "postOnly", this.safeBool2(order, "post_only", "po") },
            { "reduceOnly", this.safeBool(order, "ro") },
            { "side", side },
            { "price", price },
            { "triggerPrice", null },
            { "stopLossPrice", stopLossPrice },
            { "takeProfitPrice", takeProfitPrice },
            { "amount", this.safeString2(order, "quantity", "qty") },
            { "cost", null },
            { "average", null },
            { "filled", this.safeString2(order, "filled_quantity", "fill") },
            { "remaining", this.safeString2(order, "resting_quantity", "rest") },
            { "status", this.parseOrderStatus(this.safeString(order, "status")) },
            { "fee", null },
            { "trades", null },
        }, marketResolved);
    }

    /**
     * @method
     * @name polymarket#fetchBalance
     * @description query for the account equity, the free order margin and the used initial margin
     * @see https://docs.polymarket.com/perps/trading
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [balance structure]{@link https://docs.ccxt.com/#/?id=balance-structure}
     */
    public async override Task<ccxt.Balances> FetchBalance(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        await this.loadProxyCredentials();
        Dictionary<string, object> response = await this.privateGetAccountPortfolio(parameters);
        //
        //     {
        //         "positions": [],
        //         "margin": {
        //             "total_account_value": "100.00",
        //             "available_order_margin": "90.00",
        //             "total_initial_margin": "10.00",
        //             "total_maintenance_margin": "5.00",
        //             "total_position_value": "50.00"
        //         },
        //         "withdrawable": "90.00",
        //         "in_liquidation": false,
        //         "timestamp": 1788546565789
        //     }
        //
        IDictionary<string, object> margin = this.safeDict(response, "margin", new Dictionary<string, object>() {});
        Int64? timestamp = this.safeInteger(response, "timestamp");
        Dictionary<string, object> result = new Dictionary<string, object>() {
            { "info", response },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
        };
        Dictionary<string, object> account = this.account();
        account["total"] = this.safeString(margin, "total_account_value");
        account["free"] = this.safeString(margin, "available_order_margin");
        account["used"] = this.safeString(margin, "total_initial_margin");
        // pUSD is the only collateral asset on the venue
        result["PUSD"] = account;
        return ccxt.BaseExchange.ToBalances(this.safeBalance(result));
    }

    /**
     * @method
     * @name polymarket#fetchPositions
     * @description fetch all open positions
     * @see https://docs.polymarket.com/perps/trading
     * @param {string[]} [symbols] list of unified market symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [position structures]{@link https://docs.ccxt.com/#/?id=position-structure}
     */
    public async override Task<List<ccxt.Position>> FetchPositions(IList<object> symbols = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        await this.loadProxyCredentials();
        IList<object> symbolsNormalized = this.marketSymbols(symbols);
        Dictionary<string, object> response = await this.privateGetAccountPortfolio(parameters);
        Int64? timestamp = this.safeInteger(response, "timestamp");
        List<object> rows = this.safeList(response, "positions", new List<object>() {});
        List<object> positions = new List<object>() {};
        for (int i = 0; i < rows.Count; i++)
        {
            // the wrapper timestamp flows into the parser through the merged input
            Dictionary<string, object> extended = this.extend(rows[i], new Dictionary<string, object>() {
                { "timestamp", timestamp },
            });
            positions.Add(this.parsePosition(extended));
        }
        return ccxt.BaseExchange.ToPositionList(this.filterByArrayPositions(positions, "symbol", symbolsNormalized));
    }

    /**
     * @method
     * @name polymarket#fetchPosition
     * @description fetch data on a single open contract trade position
     * @see https://docs.polymarket.com/perps/trading
     * @param {string} symbol unified market symbol of the market the position is held in
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [position structure]{@link https://docs.ccxt.com/#/?id=position-structure}
     */
    public async override Task<ccxt.Position> FetchPosition(string symbol, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        List<object> positions = ccxt.BaseExchange.FromPositionList(await this.FetchPositions(new List<object>() {symbol}, parameters));
        IDictionary<string, object> position = this.safeDict(positions, 0);
        return ccxt.BaseExchange.ToPosition(position);
    }

    public override Dictionary<string, object> parsePosition(object position, IDictionary<string, object> market = null)
    {
        //
        //     {
        //         "instrument_id": 6,
        //         "symbol": "BTC-USD",
        //         "size": "-0.001",
        //         "entry_price": "79650.0",
        //         "leverage": 10,
        //         "cross": true,
        //         "initial_margin": "7.97",
        //         "maintenance_margin": "3.99",
        //         "position_value": "79.65",
        //         "liquidation_price": "85000.0",
        //         "unrealized_pnl": "-0.10",
        //         "return_on_equity": "-0.0125",
        //         "cumulative_funding": "0.01",
        //         "timestamp": 1788546565789
        //     }
        //
        string? marketId = this.safeString(position, "instrument_id");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        string? size = this.safeString(position, "size");
        string? side = null;
        if ((size != null))
        {
            bool isLong = Precise.stringGt(size, "0");
            side = isLong ? "long" : "short";
        }
        bool? isCross = this.safeBool(position, "cross");
        string? marginMode = null;
        if ((isCross != null))
        {
            marginMode = isCross == true ? "cross" : "isolated";
        }
        Int64? timestamp = this.safeInteger(position, "timestamp");
        string? roe = this.safeString(position, "return_on_equity");
        double? percentage = null;
        if ((roe != null))
        {
            percentage = this.parseNumber(Precise.stringMul(roe, "100"));
        }
        return this.safePosition(new Dictionary<string, object>() {
            { "info", position },
            { "id", null },
            { "symbol", (marketResolved != null && marketResolved.ContainsKey("symbol") ? marketResolved["symbol"] : null) },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastUpdateTimestamp", null },
            { "initialMargin", this.safeNumber(position, "initial_margin") },
            { "initialMarginPercentage", null },
            { "maintenanceMargin", this.safeNumber(position, "maintenance_margin") },
            { "maintenanceMarginPercentage", null },
            { "entryPrice", this.safeNumber(position, "entry_price") },
            { "notional", this.safeNumber(position, "position_value") },
            { "leverage", this.safeInteger(position, "leverage") },
            { "unrealizedPnl", this.safeNumber(position, "unrealized_pnl") },
            { "realizedPnl", null },
            { "contracts", this.parseNumber(Precise.stringAbs(size)) },
            { "contractSize", (marketResolved != null && marketResolved.ContainsKey("contractSize") ? marketResolved["contractSize"] : null) },
            { "marginRatio", null },
            { "liquidationPrice", this.parseNumber(this.omitZero(this.safeString(position, "liquidation_price"))) },
            { "markPrice", null },
            { "lastPrice", null },
            { "collateral", this.safeNumber(position, "initial_margin") },
            { "marginMode", marginMode },
            { "side", side },
            { "percentage", percentage },
            { "hedged", false },
            { "stopLossPrice", null },
            { "takeProfitPrice", null },
        });
    }

