    /**
     * @method
     * @name polymarket#fetchFundingHistory
     * @description fetch the funding payments paid and received on the open positions of the account
     * @see https://docs.polymarket.com/perps/trading
     * @param {string} [symbol] unified market symbol
     * @param {int} [since] timestamp in ms of the earliest funding payment
     * @param {int} [limit] the maximum number of funding payment structures to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms of the latest funding payment
     * @returns {object[]} a list of [funding history structures]{@link https://docs.ccxt.com/#/?id=funding-history-structure}
     */
    public async override Task<List<ccxt.FundingHistory>> FetchFundingHistory(string? symbol = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        await this.loadProxyCredentials();
        IDictionary<string, object> market = null;
        Dictionary<string, object> request = new Dictionary<string, object>() {};
        if ((symbol != null))
        {
            Dictionary<string, object> symbolMarket = this.market(symbol);
            market = symbolMarket;
            request["instrument_id"] = (symbolMarket != null && symbolMarket.ContainsKey("id") ? symbolMarket["id"] : null);
        }
        if ((since != null))
        {
            request["start_timestamp"] = since;
        }
        Int64? until = this.safeInteger(parameters, "until");
        object paramsOmitted = parameters;
        if ((until != null))
        {
            paramsOmitted = this.omit(paramsOmitted, "until");
            request["end_timestamp"] = until;
        }
        Dictionary<string, object> response = await this.privateGetAccountFunding(this.extend(request, paramsOmitted));
        //
        //     {
        //         "data": [
        //             {
        //                 "id": 123,
        //                 "instrument_id": 6,
        //                 "size": "0.001",
        //                 "funding_rate": "0.0000125",
        //                 "funding_asset": "USDC",
        //                 "funding": "-0.01",
        //                 "timestamp": 1788546565789
        //             }
        //         ],
        //         "more": false
        //     }
        //
        List<object> data = this.safeList(response, "data", new List<object>() {});
        List<object> result = new List<object>() {};
        for (int i = 0; i < data.Count; i++)
        {
            object entry = data[i];
            string? marketId = this.safeString(entry, "instrument_id");
            Int64? timestamp = this.safeInteger(entry, "timestamp");
            result.Add(new Dictionary<string, object>() {
                { "info", entry },
                { "symbol", this.safeSymbol(marketId, market) },
                { "code", this.safeCurrencyCode(this.safeString(entry, "funding_asset")) },
                { "timestamp", timestamp },
                { "datetime", this.iso8601(timestamp) },
                { "id", this.safeString(entry, "id") },
                { "amount", this.safeNumber(entry, "funding") },
            });
        }
        return ccxt.BaseExchange.ToFundingHistoryList(this.filterBySymbolSinceLimit(result, symbol, since, limit));
    }

    public virtual string? parseTransactionStatus(object status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "pending", "pending" },
            { "confirmed", "ok" },
            { "removed", "failed" },
            { "failed", "failed" },
        };
        return this.safeString(statuses, status, status);
    }

    public override Dictionary<string, object> parseTransaction(object transaction, object currency = null)
    {
        //
        // deposit row
        //
        //     {
        //         "hash": "0x...",
        //         "asset": "USDC",
        //         "amount": "100",
        //         "from": "0x...",
        //         "to": "0x...",
        //         "status": "confirmed",
        //         "confirmations": 10,
        //         "required_confirmations": 10,
        //         "created_timestamp": 1788546565789,
        //         "confirmed_timestamp": 1788546570789
        //     }
        //
        // withdrawal row
        //
        //     {
        //         "withdraw_id": 123,
        //         "asset": "USDC",
        //         "amount": "100",
        //         "to": "0x...",
        //         "fee": "0.1",
        //         "status": "pending",
        //         "hash": "0x",
        //         "confirmations": 0,
        //         "required_confirmations": 10,
        //         "created_timestamp": 1788546565789
        //     }
        //
        string? withdrawId = this.safeString(transaction, "withdraw_id");
        string type = ((withdrawId != null)) ? "withdrawal" : "deposit";
        string? currencyId = this.safeString(transaction, "asset");
        string? code = this.safeCurrencyCode(currencyId, currency);
        Int64? timestamp = this.safeInteger(transaction, "created_timestamp");
        string? rawHash = this.safeString(transaction, "hash");
        // the venue reports the literal 0x prefix while the transaction is unmined
        string? txid = (rawHash == "0x") ? null : rawHash;
        string? feeCost = this.safeString(transaction, "fee");
        Dictionary<string, object> fee = null;
        if ((feeCost != null))
        {
            fee = new Dictionary<string, object>() {
                { "cost", this.parseNumber(feeCost) },
                { "currency", code },
            };
        }
        return new Dictionary<string, object>() {
            { "info", transaction },
            { "id", withdrawId },
            { "txid", txid },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "network", null },
            { "address", null },
            { "addressTo", this.safeString(transaction, "to") },
            { "addressFrom", this.safeString(transaction, "from") },
            { "tag", null },
            { "tagTo", null },
            { "tagFrom", null },
            { "type", type },
            { "amount", this.safeNumber(transaction, "amount") },
            { "currency", code },
            { "status", this.parseTransactionStatus(this.safeString(transaction, "status")) },
            { "updated", this.safeInteger(transaction, "confirmed_timestamp") },
            { "comment", null },
            { "internal", false },
            { "fee", fee },
        };
    }

    /**
     * @method
     * @name polymarket#fetchDeposits
     * @description fetch all deposits made to the account
     * @see https://docs.polymarket.com/perps/fund-your-account
