    /**
     * @method
     * @name polymarket#withdraw
     * @description withdraw the collateral asset to the polymarket wallet of the account, the request is signed by the wallet key with the withdraw struct of the deposit contract
     * @see https://docs.polymarket.com/perps/fund-your-account
     * @param {string} code unified currency code
     * @param {float} amount the amount to withdraw
     * @param {string} address the address to withdraw to
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/#/?id=transaction-structure}
     */
    public async override Task<ccxt.Transaction> Withdraw(string code, double amount, string address, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        this.checkRequiredCredentials();
        await this.loadMarkets();
        Dictionary<string, object> currency = this.currency(code);
        string owner = this.ethGetAddressFromPrivateKey(this.privateKey);
        IDictionary<string, object> collateral = this.safeDict(this.options, "collateral", new Dictionary<string, object>() {});
        string? tokenAddress = this.safeString(collateral, "address");
        string? decimals = this.safeString(collateral, "decimals", "6");
        string? precision = this.parsePrecision(decimals);
        // the signed amount is denominated using raw base units of the token
        string precised = this.decimalToPrecision(this.numberToString(amount), TRUNCATE, this.parseNumber(precision), TICK_SIZE);
        string? baseUnits = Precise.stringDiv(precised, precision);
        Int64 ts = this.seconds();
        int salt = this.randNumber(9);
        Int64? chainId = this.safeInteger(this.options, "chainId", 137);
        string? contract = this.safeString(this.options, "depositContract", "0xDCa4af75705dbB50f62437045afF9921947917d2");
        Dictionary<string, object> domain = new Dictionary<string, object>() {
            { "name", "Polymarket" },
            { "version", "1" },
            { "chainId", chainId },
            { "verifyingContract", contract },
        };
        Dictionary<string, object> messageTypes = new Dictionary<string, object>() {
            { "Withdraw", new List<object>() {new Dictionary<string, object>() {
    { "name", "account" },
    { "type", "address" },
}, new Dictionary<string, object>() {
    { "name", "token" },
    { "type", "address" },
}, new Dictionary<string, object>() {
    { "name", "amount" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "fee" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "to" },
    { "type", "address" },
}, new Dictionary<string, object>() {
    { "name", "salt" },
    { "type", "uint64" },
}, new Dictionary<string, object>() {
    { "name", "ts" },
    { "type", "uint64" },
}} },
        };
        Dictionary<string, object> message = new Dictionary<string, object>() {
            { "account", owner },
            { "token", tokenAddress },
            { "amount", this.parseToInt(baseUnits) },
            { "fee", 0 },
            { "to", address },
            { "salt", salt },
            { "ts", ts },
        };
        byte[] encoded = this.ethEncodeStructuredData(domain, messageTypes, message);
        string signature = this.signMessage(encoded, this.privateKey);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "op", new Dictionary<string, object>() {
                { "type", "withdraw" },
                { "args", new Dictionary<string, object>() {
                    { "account", owner },
                    { "token", tokenAddress },
                    { "amount", baseUnits },
                    { "to", address },
                } },
            } },
            { "salt", salt },
            { "sig", signature },
            { "ts", ts },
        };
        Dictionary<string, object> response = await this.tradePostAccountWithdraw(this.extend(request, parameters));
        //
        //     { "status": "ok", "withdraw_id": 123 }
        //
        // the ack status is the request discriminator, the accepted
        // withdrawal itself starts out pending
        Dictionary<string, object> stripped = this.omit(response, "status");
        Dictionary<string, object> transaction = this.parseTransaction(stripped, currency);
        transaction["status"] = "pending";
        return ccxt.BaseExchange.ToTransaction(transaction);
    }

    /**
     * @method
     * @name polymarket#fetchLeverage
     * @description fetch the leverage and the margin mode configured for a market
     * @see https://docs.polymarket.com/perps/trading
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [leverage structure]{@link https://docs.ccxt.com/#/?id=leverage-structure}
     */
    public async override Task<ccxt.Leverage> FetchLeverage(string symbol, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        await this.loadProxyCredentials();
        Dictionary<string, object> market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "instrument_id", (market.ContainsKey("id") ? market["id"] : null) },
        };
        List<object> response = await this.privateGetAccountConfig(this.extend(request, parameters));
        //
        //     [ { "instrument_id": 1, "leverage": 10, "cross": true } ]
        //
        // select the requested row explicitly in case the documented
        // instrument_id filter is ever ignored the way the tickers one is
        for (int i = 0; i < (response?.Count ?? 0); i++)
        {
            IDictionary<string, object> row = this.safeDict(response, i, new Dictionary<string, object>() {});
            string? rowId = this.safeString(row, "instrument_id");
            if (isEqual(rowId, (market.ContainsKey("id") ? market["id"] : null)))
            {
                return ccxt.BaseExchange.ToLeverage(this.parseLeverage(row, market));
            }
        }
        throw new BadSymbol (((this.id + " fetchLeverage() could not find the configuration for ") + symbol)) ;
    }

    public override Dictionary<string, object> parseLeverage(object leverage, IDictionary<string, object> market = null)
    {
        string? marketId = this.safeString(leverage, "instrument_id");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        bool? isCross = this.safeBool(leverage, "cross");
        string? marginMode = null;
        if ((isCross != null))
        {
            marginMode = isCross == true ? "cross" : "isolated";
        }
        Int64? value = this.safeInteger(leverage, "leverage");
        return new Dictionary<string, object>() {
            { "info", leverage },
            { "symbol", (marketResolved != null && marketResolved.ContainsKey("symbol") ? marketResolved["symbol"] : null) },
            { "marginMode", marginMode },
            { "longLeverage", value },
            { "shortLeverage", value },
        };
    }

    /**
     * @method
     * @name polymarket#fetchMarginMode
     * @description fetches the margin mode configured for a market
     * @see https://docs.polymarket.com/perps/trading
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [margin mode structure]{@link https://docs.ccxt.com/#/?id=margin-mode-structure}
     */
    public async override Task<ccxt.MarginMode> FetchMarginMode(string symbol, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> leverage = ccxt.BaseExchange.FromLeverage(await this.FetchLeverage(symbol, parameters));
        return ccxt.BaseExchange.ToMarginMode(new Dictionary<string, object>() {             { "info", this.safeDict(leverage, "info") },             { "symbol", this.safeString(leverage, "symbol") },             { "marginMode", this.safeString(leverage, "marginMode") },         });
    }

    /**
     * @method
     * @name polymarket#setLeverage
     * @description set the level of leverage for a market, optionally switching the margin mode at the same time
     * @see https://docs.polymarket.com/perps/trading
     * @param {float} leverage the rate of leverage
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.marginMode] 'cross' or 'isolated', the venue keeps the current mode when omitted is not supported - the default is cross
     * @returns {object} the raw acknowledgement of the venue
     */
    public async override Task<Dictionary<string, object>> SetLeverage(Int64 leverage, string symbol = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((symbol == null))
        {
            throw new ArgumentsRequired ((this.id + " setLeverage() requires a symbol argument")) ;
        }
        await this.loadMarkets();
        Dictionary<string, object> market = this.market(symbol);
        string? marginMode = null;
        object paramsOmitted = parameters;
        (string?, object) marginModeparamsOmittedVariable = this.handleMarginModeAndParams("setLeverage", paramsOmitted, "cross");
        marginMode = marginModeparamsOmittedVariable.Item1;
        paramsOmitted = marginModeparamsOmittedVariable.Item2;
        bool isCross = (marginMode != "isolated");
        Int64? instrumentId = this.parseToInt((market.ContainsKey("id") ? market["id"] : null));
        Int64? leverageInt = this.parseToInt(leverage);
        List<object> signable = new List<object>() {"updateLeverage", new List<object>() {instrumentId, leverageInt, isCross}};
        Dictionary<string, object> bodyOp = new Dictionary<string, object>() {
            { "type", "updateLeverage" },
            { "args", new Dictionary<string, object>() {
                { "cross", isCross },
                { "iid", instrumentId },
                { "lev", leverageInt },
            } },
        };
        object signed = await this.signPerpsOp(signable, bodyOp);
        Dictionary<string, object> response = await this.tradePatchTradeLeverage(signed);
        //
        //     { "status": "ok", "instrument_id": 1, "leverage": 10, "cross": true }
        //
        return response;
    }

    /**
     * @method
     * @name polymarket#setMarginMode
     * @description set the margin mode of a market, the venue updates the mode and the leverage together
     * @see https://docs.polymarket.com/perps/trading
     * @param {string} marginMode 'cross' or 'isolated'
     * @param {string} [symbol] unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {float} params.leverage the rate of leverage to set together with the mode
     * @returns {object} the raw acknowledgement of the venue
     */
    public async override Task<Dictionary<string, object>> SetMarginMode(string marginMode, string symbol = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((symbol == null))
        {
            throw new ArgumentsRequired ((this.id + " setMarginMode() requires a symbol argument")) ;
        }
        Int64? leverage = this.safeInteger(parameters, "leverage");
        if ((leverage == null))
        {
            throw new ArgumentsRequired ((this.id + " setMarginMode() requires a params.leverage argument, the venue updates the mode and the leverage in one operation")) ;
        }
        IDictionary<string, object> paramsOmitted = ((IDictionary<string, object>)this.omit(parameters, "leverage"));
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "marginMode", marginMode },
        };
        Int64? leverageInt = this.parseToInt(leverage);
        return await this.SetLeverage(ccxt.BaseExchange.ToInt64ArgRequired(leverageInt), symbol, this.extend(request, paramsOmitted));
    }

    /**
     * @method
     * @ignore
     * @name polymarket#modifyMarginHelper
     * @description adds margin to an isolated position or removes some, the amount is a signed decimal in the collateral asset
     * @param {string} symbol unified market symbol
     * @param {float} amount the amount of margin to move
     * @param {string} type 'add' or 'reduce'
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [margin structure]{@link https://docs.ccxt.com/#/?id=add-margin-structure}
     */
    public async virtual Task<Dictionary<string, object>> modifyMarginHelper(object symbol, object amount, string type, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        Dictionary<string, object> market = this.market(symbol);
        Int64? instrumentId = this.parseToInt((market.ContainsKey("id") ? market["id"] : null));
        IDictionary<string, object> collateral = this.safeDict(this.options, "collateral", new Dictionary<string, object>() {});
        string? decimals = this.safeString(collateral, "decimals", "6");
        string? precision = this.parsePrecision(decimals);
        string amountString = this.decimalToPrecision(this.numberToString(amount), TRUNCATE, this.parseNumber(precision), TICK_SIZE);
        if ((type == "reduce"))
        {
            amountString = ("-" + amountString);
        }
        List<object> signable = new List<object>() {"updateMargin", new List<object>() {instrumentId, amountString}};
        Dictionary<string, object> bodyOp = new Dictionary<string, object>() {
            { "type", "updateMargin" },
            { "args", new Dictionary<string, object>() {
                { "amt", amountString },
                { "iid", instrumentId },
            } },
        };
        object signed = await this.signPerpsOp(signable, bodyOp);
        Dictionary<string, object> response = await this.tradePatchTradeMargin(signed);
        //
        //     { "status": "ok" }
        //
        return new Dictionary<string, object>() {
            { "info", response },
            { "symbol", (market.ContainsKey("symbol") ? market["symbol"] : null) },
            { "type", type },
            { "marginMode", "isolated" },
            { "amount", this.parseNumber(amountString) },
            { "total", null },
            { "code", (market.ContainsKey("settle") ? market["settle"] : null) },
            { "status", "ok" },
            { "timestamp", null },
            { "datetime", null },
        };
    }

