    public virtual string? hashMessage(object message)
    {
        return ((string?)((object)(("0x" + (this.hash(message, keccak, "hex"))))));
    }

    public virtual string signHash(object hash, object privateKey)
    {
        Dictionary<string, object> signature = ecdsa(slice(hash, -64, null), slice(privateKey, -64, null), secp256k1, null);
        string? r = ((string)(signature != null && signature.ContainsKey("r") ? signature["r"] : null));
        string? sVal = ((string)(signature != null && signature.ContainsKey("s") ? signature["s"] : null));
        string v = this.intToBase16(this.sum(27, (signature != null && signature.ContainsKey("v") ? signature["v"] : null)));
        return ((("0x" + ((r as String).PadLeft(Convert.ToInt32(64), Convert.ToChar("0")))) + ((sVal as String).PadLeft(Convert.ToInt32(64), Convert.ToChar("0")))) + v);
    }

    public virtual string signMessage(object message, object privateKey)
    {
        return this.signHash(this.hashMessage(message), privateKey);
    }

    /**
     * @method
     * @name polymarket#createProxyCredentials
     * @description provisions fresh trading session credentials - generates a proxy keypair, registers it with an EIP-712 CreateProxy message signed by the wallet key and caches the returned secret, the venue keeps the session valid for the requested lifetime
     * @see https://docs.polymarket.com/perps/authenticated-sessions
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} the session credentials, holding the proxy address, the proxy private key, the secret and the expiry timestamp
     */
    public async virtual Task<object> createProxyCredentials(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        this.checkRequiredCredentials();
        // the session key derives from an ecdsa signature under the wallet
        // key over a timestamped nonce - unpredictable without the wallet
        // secret and unique per provisioning, the paradex stark-key idiom
        string nonceMessage = ((("polymarket-perps-proxy:" + this.milliseconds().ToString()) + ":") + this.randNumber(9).ToString());
        string seedSignature = this.signMessage(nonceMessage, this.privateKey);
        string proxyPrivateKey = ((string)this.hash(this.encode(seedSignature), keccak, "hex"));
        string proxyAddress = this.ethGetAddressFromPrivateKey(proxyPrivateKey);
        string owner = this.ethGetAddressFromPrivateKey(this.privateKey);
        Int64 ts = this.milliseconds();
        Int64? lifetime = this.safeInteger(this.options, "proxyExpiry", 604800000);
        Int64 expiry = this.sum(ts, lifetime);
        int salt = this.randNumber(9);
        Int64? chainId = this.safeInteger(this.options, "chainId", 137);
        Dictionary<string, object> domain = new Dictionary<string, object>() {
            { "name", "Polymarket" },
            { "version", "1" },
            { "chainId", chainId },
        };
        Dictionary<string, object> messageTypes = new Dictionary<string, object>() {
            { "CreateProxy", new List<object>() {new Dictionary<string, object>() {
    { "name", "addr" },
    { "type", "address" },
}, new Dictionary<string, object>() {
    { "name", "exp" },
    { "type", "uint64" },
}, new Dictionary<string, object>() {
    { "name", "salt" },
    { "type", "uint64" },
}, new Dictionary<string, object>() {
    { "name", "ts" },
    { "type", "uint64" },
}} },
        };
        Dictionary<string, object> message = new Dictionary<string, object>() {
            { "addr", proxyAddress },
            { "exp", expiry },
            { "salt", salt },
            { "ts", ts },
        };
        byte[] encoded = this.ethEncodeStructuredData(domain, messageTypes, message);
        string signature = this.signMessage(encoded, this.privateKey);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "op", new Dictionary<string, object>() {
                { "type", "createProxy" },
                { "args", new Dictionary<string, object>() {
                    { "expiry", expiry },
                    { "owner", owner },
                    { "proxy", proxyAddress },
                } },
            } },
            { "salt", salt },
            { "sig", signature },
            { "ts", ts },
        };
